'use strict';
navItems.splice(3,0,['banking','Kontoauszüge','wallet'],['inbox','Belege zuordnen','check']);
Object.assign(app,{bankData:null,bankYear:null,bankPreview:null,bankFile:null,intakeJobs:[],inboxMonth:'',inboxFilter:'all',inboxSearch:'',reviewQueue:Promise.resolve(),previewPending:{}});
const bankingBaseRender=render,bankingBaseAction=action,bankingBaseSubmit=submit,bankingBaseTxForm=transactionForm;
const accountName=id=>app.data.bank_accounts?.find(a=>a.id===id)?.name||'Ohne Konto';
const rowStatus={ready:'Bereit',duplicate:'Bereits vorhanden',manual_review:'Doppelung prüfen',outside_year:'Anderes Jahr',error:'Fehler'};
const moneyInput=c=>(c<0?'-':'')+Math.floor(Math.abs(c)/100)+','+String(Math.abs(c)%100).padStart(2,'0');
function accountsForYear(year){return (app.data.bank_accounts||[]).filter(a=>(!a.opened_on||a.opened_on.slice(0,4)<=String(year))&&(a.status!=='closed'||!a.closed_on||a.closed_on.slice(0,4)>=String(year)));}
function accountCard(a){return `<div class="account-line"><div><strong>${esc(a.name)}</strong><p class="small muted">${a.status==='closed'?`Archiviert · letzter Kontotag ${fmtDate(a.closed_on)}`:a.status==='planned'?'Geplant · vor der ersten Nutzung aktivieren':'Aktiv'}${a.iban?' · '+esc(a.iban.slice(0,4))+' … '+esc(a.iban.slice(-4)):''}</p></div>${button('Bearbeiten','edit-bank','edit','small',`data-id="${a.id}"`)}</div>`;}
function bankView(){const data=app.bankYear===app.year?app.bankData:null,accounts=app.data.bank_accounts||[];
 return head('Deine Kontoauszüge.','Einmal hochladen. In Ruhe prüfen. Später fortsetzen.',button('Papierkorb','open-trash','trash','ghost small'))+paymentTabs('banking')+
 `<section class="panel intake-hero compact-intake"><button class="dropzone" id="bank-dropzone" data-action="bank-import"><span class="upload-symbol">${icon('upload')}</span><span class="upload-copy"><strong>Auszug hier ablegen</strong><small>CSV oder PDF · Volksbank, N26 und FYRST</small></span><span class="upload-choose">Datei auswählen ${icon('arrow')}</span></button></section>
 ${data?`<section class="panel section-gap"><div class="panel-header"><h2>Gespeicherte Auszüge · ${app.year}</h2></div><div class="panel-body">${uploadRows(data)||'<p class="muted">Noch kein Auszug gespeichert. Ziehe deine erste Datei in das Feld oben.</p>'}</div></section>`:'<p class="small muted section-gap">Auszüge laden …</p>'}
 <details class="home-details"><summary>Konten verwalten · ${accounts.filter(a=>a.status==='active').length} aktiv</summary><div class="home-details-body">${accounts.filter(a=>a.status!=='closed').map(accountCard).join('')}<p class="small muted section-gap">Eigene IBANs eintragen, damit Eigenüberträge erkannt werden. Das Archivieren hier beendet kein Bankkonto.</p>${accounts.some(a=>a.status==='closed')?`<details class="source-details"><summary>Archivierte Konten · Historie erhalten</summary>${accounts.filter(a=>a.status==='closed').map(accountCard).join('')}</details>`:''}</div></details>
 ${data&&(data.candidates.length||data.transfers.length||data.unpaired.length)?`<details class="home-details"${data.candidates.length?' open':''}><summary>Eigenüberträge · ${data.candidates.length} Vorschläge prüfen</summary><div class="home-details-body">${data.candidates.map(p=>`<div class="account-line"><div><strong>${money(p.incoming.amount_cents)}</strong><p>${esc(p.outgoing.account_name)} → ${esc(p.incoming.account_name)}</p><p class="small muted">${fmtDate(p.outgoing.booked_on)} / ${fmtDate(p.incoming.booked_on)}</p></div>${button('Eigenübertrag bestätigen','confirm-transfer','check','small',`data-out="${p.outgoing.id}" data-in="${p.incoming.id}"`)}</div>`).join('')}<p class="small muted">${data.transfers.length} verbundene Paare · ${data.unpaired.length} anhand eigener IBAN neutrale Kontoseiten ohne passendes Gegenstück. Betragsgleichheit allein ist kein Nachweis.</p></div></details>`:''}
 <p class="page-note">Importe bleiben lokal. Die KI macht Vorschläge; du bestätigst die Übernahme. Monat und Jahr richten sich hier nach dem Zahlungsdatum. Steuerliche Jahreszuordnung und Umsatzsteuer bleiben gesondert zu prüfen.</p>`;
}
async function loadBank(){const year=app.year;const [data,intake]=await Promise.all([api('/api/banking?year='+year),api('/api/intake?year='+year)]);if(app.year!==year)return;app.bankData=data;app.bankYear=year;app.intakeJobs=intake.jobs;app.uploadTrash=intake.trash||[];app.intakeCapabilities=intake.capabilities;if(app.view==='banking')render();clearTimeout(app.bankPoll);if(intake.jobs.some(j=>['queued','running'].includes(j.state)))app.bankPoll=setTimeout(()=>loadBank().catch(e=>toast(e.message,true)),3000);}
render=function(){if(!app.data)return;if(!['banking','inbox'].includes(app.view))return bankingBaseRender();const view=app.view;app.view='overview';bankingBaseRender();app.view=view;$('#main').innerHTML=view==='banking'?bankView():inboxView();$('#breadcrumb-current').textContent=view==='banking'?'Kontoauszüge':'Belege zuordnen';document.querySelectorAll('#nav .nav-item').forEach(a=>{const active=a.dataset.view===view;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const drop=$('#bank-dropzone');if(drop){drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drag');});drop.addEventListener('dragleave',()=>drop.classList.remove('drag'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('drag');if(e.dataTransfer.files.length!==1)return toast('Bitte eine CSV- oder PDF-Datei pro Import.',true);bankImportForm(null,e.dataTransfer.files[0]);});}if(app.bankYear!==app.year)loadBank().catch(e=>toast(e.message,true));};
function bankAccountForm(id){const a=app.data.bank_accounts.find(a=>a.id===id);showModal('Konto verwalten',`<form id="bank-account-form" data-id="${id}"><div class="modal-body"><div class="form-result" role="alert"></div>${field('Anzeigename','name',a.name,'text','required')}${field('Eigene IBAN','iban',a.iban,'text','placeholder="DE…" autocomplete="off"')}${select('Status','status',[['planned','Geplant'],['active','Aktiv'],['closed','Archiviert – Historie behalten']],a.status)}<div class="field-row">${field('Erster Kontotag (optional)','opened_on',a.opened_on,'date')}${field('Letzter Kontotag (beim Archivieren)','closed_on',a.closed_on,'date')}</div><p class="small muted">Nach dem letzten Kontotag wird das Konto für neue Zahlungen ausgeblendet. Frühere Buchungen und Belege bleiben zugänglich. Für Nachträge zuerst das damalige Zahlungsdatum wählen.</p><details class="advanced-details"><summary>Bank & Rücklagen</summary>${select('Bank','bank',[['volksbank','Volksbank'],['n26','N26'],['fyrst','FYRST'],['other','Andere']],a.bank)}${select('Verwendung','role',[['main','Hauptkonto'],['tax','Steuerkonto'],['historical','Bisheriges Konto']],a.role)}${field('Deine Rücklagenquote in %','reserve_percent',a.reserve_percent,'number','required min="30" max="45" step="1"')}<p class="small muted">Dein Sparplan, keine berechnete Steuerschuld. Löst keine Zahlung aus.</p></details></div><div class="modal-footer"><button type="submit" class="btn primary">Konto speichern</button></div></form>`);}
function bankImportForm(accountId=null,file=null){app.bankFile=file;app.bankPreview=null;const list=accountsForYear(app.year);showModal('Kontoauszug hochladen',`<form id="bank-import-form"><div class="modal-body"><div class="form-result" role="alert"></div><div class="field-row">${select('Welches Konto?','account_id',list.map(a=>[a.id,a.name+(a.status==='closed'?' · Archiv':'' )]),accountId||list.find(a=>a.status==='active')?.id||list[0]?.id||'')}${select('Arbeitsjahr','year',years(),app.year)}</div><div class="field"><label for="bank-csv-file">CSV oder PDF auswählen</label><input id="bank-csv-file" type="file" accept=".csv,.pdf,text/csv,application/pdf"><p id="bank-file-label" class="small muted">${file?esc(file.name):'CSV bis 10 MB · PDF bis 20 MB, maximal 60 Seiten'}</p></div><label class="check"><input type="checkbox" name="use_ai" checked>Mit meinen drei lokalen KIs vorsortieren</label><p class="small muted">Zuerst wird dein Original gespeichert. Danach prüfst du die erkannten Zahlungen und gibst sie frei. Die KIs helfen bei der Einordnung. Erkannte Volksbank-Tabellen funktionieren auch ohne KI; andere PDF-Layouts benötigen Ollama und Scans zusätzlich OCR.</p></div><div class="modal-footer"><button class="btn primary" type="submit">Auszug speichern & öffnen</button></div></form>`);}
const mappingLabels={date:'Buchungsdatum',value_date:'Wertstellung',amount:'Betrag mit Vorzeichen',debit:'Soll-Betrag',credit:'Haben-Betrag',direction:'Soll/Haben',currency:'Währung',partner:'Empfänger / Auftraggeber',iban:'Gegen-IBAN',own_iban:'Eigene IBAN',purpose:'Verwendungszweck',type:'Buchungstext',reference:'End-to-End-Referenz',transaction_id:'Eindeutige Bank-ID'};
function mappingMarkup(p){return `<details class="mapping-details"${p.errors.length?' open':''}><summary>CSV-Format anpassen (bei Erkennungsproblemen)</summary><div class="field-row">${field('Kopfzeile (ab 1)','header_row',p.header_row+1,'number','min="1" max="35"')}${select('Trennzeichen','delimiter',[[';','Semikolon'],[',','Komma'],['\t','Tabulator']],p.delimiter)}</div><div class="field-row">${select('Zeichencodierung','encoding',[['utf-8-sig','UTF-8'],['cp1252','Windows-1252'],['utf-16','UTF-16']],p.encoding)}${select('Zahlenformat','number_style',[['de','Deutsch: 1.234,56'],['en','Dezimalpunkt: 1234.56']],p.number_style)}</div><div class="mapping-grid">${Object.entries(mappingLabels).map(([k,l])=>select(l,'map_'+k,[['','Nicht zugeordnet'],...p.headers.map((h,i)=>[i,h])],p.mapping[k]??'')).join('')}</div>${button('Format anwenden · Vorschläge zurücksetzen','reparse-bank','arrow')}</details>`;}
function rowChoices(r){return r.status==='duplicate'?[['skip','Bereits vorhanden · auslassen'],...(!r.external_id?[['force_new','Echte zweite Buchung']]:[])]:['outside_year','error'].includes(r.status)?[['skip','Nicht übernehmen']]:[...(r.status==='manual_review'?[['review','Doppelung prüfen']]:[]),['create','Als neue Zahlung'],...(r.manual_matches||[]).map(t=>['link:'+t.id,'Verknüpfen: '+t.partner+' / '+t.title]),['skip','Bewusst auslassen']];}
function showBankPreview(p){app.bankPreview=p;if(p.already_imported){toast('Dieser Auszug wurde bereits übernommen.');app.bankYear=null;closeModal();return refresh();}
 const current=p.rows.filter(r=>r.status!=='outside_year'),net=current.reduce((s,r)=>s+r.amount_cents,0);
 showModal('Zahlungen prüfen',`<form id="bank-commit-form" data-id="${p.id}"><div class="modal-body import-preview"><div class="form-result" role="alert"></div><p class="save-state" role="status">Original und Vorschau gespeichert.</p><div class="detail-meta"><span class="tag">${esc(p.account.name)}</span><span class="tag">${p.year}</span><span class="tag">${current.length} Zeilen · Summe ${money(net)}</span></div><p class="small muted section-gap">Diese Summe enthält auch mögliche Doppelungen; sie ist kein Kontostand. Einordnung ist vorläufig; unbekannte Zahlungen kannst du später klären.</p><div class="actions section-gap">${button('KI vorsortieren','classify-import','spark','small',`data-id="${p.id}"`)}${button('Original öffnen','bank-original','file','small',`data-id="${p.id}" data-filename="${esc(p.filename)}"`)}</div><div id="import-ai-status" class="small muted" role="status"></div>
 ${p.source_kind==='pdf'?'':mappingMarkup(p)}${p.errors.length?`<div class="form-error">${p.errors.map(e=>`<p>Zeile ${e.line}: ${esc(e.message)}</p>`).join('')}</div>`:''}
 <div class="review-list">${p.rows.map(r=>`<article class="review-row" data-line="${r.line}"><div class="review-main"><div><strong>${esc(r.partner)}</strong><p>${esc(r.purpose)}</p><span class="small muted">${fmtDate(r.booked_on)} · Zeile ${r.line} · ${rowStatus[r.status]}</span></div><strong class="review-amount">${money(r.amount_cents)}</strong></div><div class="review-controls"><label>Bereich<select class="import-scope" aria-label="Bereich Zeile ${r.line}"${r.classification==='transfer'?' disabled':''}>${options(Object.entries(scopeNames),r.scope)}</select></label><label>Übernahme<select class="import-choice" data-line="${r.line}" aria-label="Zeile ${r.line} übernehmen"${['outside_year','error'].includes(r.status)?' disabled':''}>${options(rowChoices(r),r.choice||(r.status==='ready'?'create':r.status==='manual_review'?'review':'skip'))}</select></label></div><p class="small muted">${esc(r.ai?.reason||r.note||'')}${r.ai?.question?'<br>'+esc(r.ai.question):''}</p><details class="source-details"><summary>Kategorie, Notiz & KI-Vergleich</summary><label>Kategorie<select class="import-category">${options(categories,r.category||'Unsortiert')}</select></label><label>Notiz / Zuordnung begründen<textarea class="import-note" maxlength="2000" rows="2">${esc(r.review_note||'')}</textarea></label>${r.ai?`<p class="small">Arbeiter: ${esc(scopeNames[r.ai.worker.scope])} · ${esc(r.ai.worker.reason)}</p><p class="small">Prüfer: ${esc(scopeNames[r.ai.reviewer.scope])} · ${esc(r.ai.reviewer.reason)}</p><p class="small muted">${esc(r.ai.summary)}</p>`:'<p class="small muted">Noch keine KI-Auswertung. Deine Einordnung bleibt erhalten, wenn die KI später läuft.</p>'}</details></article>`).join('')}</div><label class="check"><input type="checkbox" name="checked" required>Konto, Jahr, Vorzeichen, Vollständigkeit und Zuordnungen am Original geprüft.</label><p class="small muted">Diese Bestätigung ist keine steuerliche Freigabe. Erforderliche Belege und die Umsatzsteuer werden gesondert geprüft.</p></div><div class="modal-footer"><button class="btn primary" type="submit"${p.errors.length||p.rows.some(r=>r.status==='error')?' disabled':''}>Auswahl übernehmen</button></div></form>`);
 $('#bank-commit-form').querySelectorAll('.review-row').forEach(row=>row.addEventListener('input',()=>queuePreviewEdit(row,p.id)));
}
function queuePreviewEdit(row,id){const edit={scope:$('.import-scope',row).value,category:$('.import-category',row).value,review_note:$('.import-note',row).value,choice:$('.import-choice',row).value};const key=id+':'+row.dataset.line;app.previewPending[key]={id,line:row.dataset.line,edit};const label=$('.save-state',row.closest('form'));app.unsavedDraft=true;label.textContent='Änderung wird gespeichert …';app.reviewQueue=app.reviewQueue.catch(()=>{}).then(async()=>{const entries=Object.entries(app.previewPending).filter(([,v])=>v.id===id);if(!entries.length)return;const edits=Object.fromEntries(entries.map(([,v])=>[v.line,v.edit]));const p=await api('/api/banking/review',{id,edits});for(const [k,v] of entries)if(app.previewPending[k]===v)delete app.previewPending[k];if(app.bankPreview?.id===id)app.bankPreview=p;app.unsavedDraft=Object.keys(app.previewPending).length>0;label.textContent=app.unsavedDraft?'Änderung wird gespeichert …':'Änderung gespeichert · '+new Date().toLocaleTimeString('de-DE');}).catch(e=>{label.textContent='Nicht gespeichert: '+e.message;app.unsavedDraft=true;throw e;});app.reviewQueue.catch(()=>{});}
async function classifyImport(id){await app.reviewQueue;const r=await api('/api/intake/start',{import_id:id});await pollIntake(r.id,'classify');return r;}
function inboxView(){const all=baseTxForYear(),filtered=all.filter(t=>(!app.inboxMonth||t.paid_on.slice(5,7)===app.inboxMonth)&&(app.inboxFilter==='all'||app.inboxFilter==='open'?(app.inboxFilter!=='open'||needsEvidence(t)):t.scope===app.inboxFilter)&&`${t.partner} ${t.title} ${t.notes||''}`.toLowerCase().includes(app.inboxSearch.toLowerCase()));const groups=new Map();for(const t of filtered){const month=t.paid_on.slice(5,7);if(!groups.has(month))groups.set(month,[]);groups.get(month).push(t);}
 return head('Deine Zahlungen.','Einordnen, Belege ergänzen, fertig für die weitere Prüfung.',button('Manuell erfassen','new-transaction','plus','primary'))+paymentTabs('inbox')+
 `<div class="toolbar"><div class="toolbar-left"><select id="inbox-month" aria-label="Monat">${options([['','Alle Monate'],...months.map((m,i)=>[String(i+1).padStart(2,'0'),m])],app.inboxMonth)}</select><select id="inbox-filter" aria-label="Filter">${options([['all','Alle Zahlungen'],['open','Noch zu bearbeiten'],...Object.entries(scopeNames)],app.inboxFilter)}</select><input type="search" id="inbox-search" aria-label="Zahlungen suchen" placeholder="Empfänger oder Zweck suchen …" value="${esc(app.inboxSearch)}"></div><span class="small muted">${all.filter(needsEvidence).length} zu bearbeiten</span></div>
 ${filtered.length?[...groups].sort((a,b)=>b[0].localeCompare(a[0])).map(([m,rows])=>`<section class="panel month-panel"><div class="panel-header"><h2>${months[Number(m)-1]} ${app.year}</h2><span class="tag">${rows.length} Zahlungen</span></div>${rows.map(t=>`<article class="evidence-row"><div class="evidence-heading"><div><strong>${esc(t.partner)}</strong><p>${esc(t.title)}</p><span class="small muted">${fmtDate(t.paid_on)} · ${esc(t.payment_method==='cash'?'Bar bezahlt':accountName(t.account_id))} · ${scopeNames[t.scope]||'Ungeklärt'}</span></div><strong class="review-amount">${t.direction==='income'?'+':'−'} ${money(t.amount_cents)}</strong></div><div class="evidence-bottom"><div>${transactionEvidence(t)}${t.receipt_note?`<p class="small muted">${esc(t.receipt_note)}</p>`:''}</div><div class="actions">${button('Beleg / Notiz','evidence','upload','small',`data-id="${t.id}"`)}${!(t.document_ids||[]).length&&t.receipt_state!=='none'&&!['private','transfer'].includes(t.scope)?button('Kein Beleg','no-evidence','','small',`data-id="${t.id}"`):''}${button('Details','edit-transaction','edit','ghost small',`data-id="${t.id}"`)}</div></div></article>`).join('')}</section>`).join(''):empty('Alles an seinem Platz.','Keine Zahlungen in dieser Auswahl. Importiere einen Auszug oder ändere den Filter.','check')}
 <p class="page-note">„Kein Beleg“ dokumentiert deine Angabe. Das bestätigt weder die Abziehbarkeit noch einen Vorsteuerabzug. Private Bewegungen brauchen keinen Betriebsrechnungsbeleg.</p>`;
}
function needsEvidence(t){return t.scope==='unknown'||t.scope==='mixed'||(t.scope==='business'&&!(t.document_ids||[]).length);}
transactionForm=function(...args){bankingBaseTxForm(...args);const t=app.data.transactions.find(t=>t.id===args[0])||{},form=$('#transaction-form');$('.modal-body',form).insertAdjacentHTML('afterbegin',select('Zugehöriges Konto','account_id',[['','Noch nicht zugeordnet']],''));const account=$('[name=account_id]',form),wrap=account.closest('.field'),payment=$('[name=payment_method]',form),paid=$('[name=paid_on]',form);wrap.classList.add('bank-account-wrap');wrap.insertAdjacentHTML('beforeend','<p class="small muted">Archiviertes Konto gesucht? Zuerst das frühere Zahlungsdatum eintragen.</p>');
 const choices=()=>{const day=paid.value||localDate(),previous=account.value||t.account_id||'';account.innerHTML=options([['','Noch nicht zugeordnet'],...(app.data.bank_accounts||[]).filter(a=>a.id===t.account_id||a.status==='active'&&(!a.opened_on||day>=a.opened_on)||a.status==='closed'&&a.closed_on&&day<=a.closed_on&&(!a.opened_on||day>=a.opened_on)).map(a=>[a.id,a.name+(a.status==='closed'?' · Archiv':'')])],previous);};choices();paid.addEventListener('change',choices);
 const sync=()=>{const cash=payment.value==='cash';wrap.classList.toggle('cash-details-hidden',cash);if(cash)account.value='';syncPaymentDetails(form);};payment.addEventListener('change',sync);account.addEventListener('change',()=>{if(account.value)payment.value='bank';sync();});sync();
 $('.receipt-picker',form).insertAdjacentHTML('afterend',select('Belegstatus','receipt_state',[['pending','Beleg wird noch ergänzt'],['none','Kein Beleg vorhanden']],t.receipt_state||'pending')+textarea('Notiz zum Beleg (optional)','receipt_note',t.receipt_note||'','maxlength="2000"'));
 if(t.bank_row_id){for(const key of ['amount','paid_on'])$(`[name="${key}"]`,form).readOnly=true;for(const key of ['direction','account_id']){const control=$(`[name="${key}"]`,form);control.addEventListener('change',()=>control.value=t[key]);}$('.modal-body',form).insertAdjacentHTML('afterbegin','<p class="small muted settings-note">Bankoriginal geschützt: Betrag, Datum, Richtung und Konto bleiben erhalten. Belege und Einordnung kannst du ergänzen.</p>');}
};
action=async function(name,el){switch(name){
 case 'bank-original':return download(`/api/banking/import/${el.dataset.id}/file`,el.dataset.filename||'Kontoauszug');
 case 'edit-bank':return bankAccountForm(el.dataset.id);
 case 'restore-matching-upload':{const form=el.closest('form');form.dataset.restoreId=el.dataset.id;try{return await submit(form);}finally{delete form.dataset.restoreId;}}
 case 'bank-import':case 'bank-pdf':return bankImportForm(el.dataset.id||null);
 case 'resume-import':await app.reviewQueue;return showBankPreview(await api('/api/banking/preview?id='+encodeURIComponent(el.dataset.id)));
 case 'classify-import':el.disabled=true;try{return await classifyImport(el.dataset.id);}finally{el.disabled=false;}
 case 'reparse-bank':{await app.reviewQueue;if(!confirm('Das neue CSV-Format setzt die Einordnung dieser Vorschau zurück. Fortfahren?'))return;const p=app.bankPreview,form=$('#bank-commit-form'),mapping={};for(const key of Object.keys(mappingLabels)){const v=$(`[name="map_${key}"]`,form).value;if(v!=='')mapping[key]=Number(v);}return showBankPreview(await api('/api/banking/preview',{import_id:p.id,account_id:p.account.id,year:p.year,filename:p.filename,options:{encoding:$('[name="encoding"]',form).value,number_style:$('[name="number_style"]',form).value,delimiter:$('[name="delimiter"]',form).value,header_row:Number($('[name="header_row"]',form).value)-1,...(Number($('[name="header_row"]',form).value)-1===p.header_row?{mapping}:{})}}));}
 case 'confirm-transfer':await api('/api/banking/transfer',{outgoing_id:el.dataset.out,incoming_id:el.dataset.in});app.bankYear=null;await refresh();return toast('Beide Kontoseiten als neutralen Eigenübertrag verbunden.');
 default:return bankingBaseAction(name,el);}};
submit=async function(form){if(!['bank-account-form','bank-import-form','bank-commit-form'].includes(form.id))return bankingBaseSubmit(form);const result=$('.form-result',form),btn=$('[type="submit"]',form);btn.disabled=true;form.inert=true;result.textContent='';try{const data=Object.fromEntries(new FormData(form));if(form.id==='bank-account-form'){await api('/api/banking/accounts',{...data,id:form.dataset.id});app.bankYear=null;closeModal();await refresh();toast('Konto gespeichert. Die Historie bleibt erhalten.');}
 else if(form.id==='bank-import-form'){const file=app.bankFile;if(!file||file.size>20*1024*1024)throw new Error('Bitte eine CSV- oder PDF-Datei bis 20 MB auswählen.');const useAI=$('[name=use_ai]',form).checked;result.textContent='Original wird gespeichert …';const r=await api('/api/intake/upload',{...data,filename:file.name,file_base64:await fileBase64(file),year:Number(data.year),...(form.dataset.restoreId?{restore_trash_id:form.dataset.restoreId}:{})});app.year=Number(data.year);app.bankYear=null;await refresh();if(r.kind==='csv'){showBankPreview(r.preview);if(useAI&&!r.restored&&!r.preview.already_imported)try{await classifyImport(r.preview.id);}catch(e){const label=$('#import-ai-status');if(label)label.textContent='Original und Vorschau gespeichert. KI noch nicht gestartet: '+e.message;}}
 else{await openIntakeJob(r.job.id);if(!r.restored&&!r.job.import_id&&!['running','queued','review'].includes(r.job.state))try{await startPdfJob(r.job.id,useAI);}catch(e){const label=$('#pdf-progress');if(label)label.textContent='Original gespeichert. '+e.message;}}}
 else{await app.reviewQueue;if(!$('[name="checked"]',form).checked)throw new Error('Bitte die Importvorschau prüfen und bestätigen.');const choices={};form.querySelectorAll('.import-choice').forEach(el=>choices[el.dataset.line]=el.value);const r=await api('/api/banking/commit',{id:form.dataset.id,checked:true,choices,pdf_selection_token:form.dataset.selectionToken});app.bankYear=null;app.suppressDraft=true;closeModal();app.suppressDraft=false;app.inboxMonth='';app.inboxFilter='all';await refresh();if(r.partial){await openIntakeJob(r.job_id);toast('Monat gespeichert. Nur offene Monate bleiben in der Prüfung.');return;}navigate('inbox');toast(`${r.imported} Zahlungen importiert · ${r.linked} verknüpft · ${r.skipped} ausgelassen.`);}}
 catch(e){result.className='form-result form-error';if(form.id==='bank-import-form'&&e.details?.kind==='upload_in_trash'){const d=e.details;result.className='form-result upload-restore-offer';result.innerHTML=`<strong>Diesen Auszug hast du schon hochgeladen.</strong><p>${esc(d.label)} · ${esc(d.year)} liegt im Papierkorb. Stelle ihn wieder her, um deinen gespeicherten Stand zu öffnen.</p><p class="small muted">${d.payments_preserved?esc(d.payments_preserved)+' bereits übernommene Zahlungen bleiben erhalten.':'Deine gespeicherten Einordnungen bleiben erhalten.'} Es entsteht kein zweiter Import.</p>${button('Wiederherstellen & öffnen','restore-matching-upload','','primary small',`data-id="${esc(d.trash_id)}"`)}`;}else result.textContent=e.message;result.scrollIntoView?.({block:'nearest'});}finally{btn.disabled=false;form.inert=false;}};
document.addEventListener('change',e=>{if(e.target.id==='bank-csv-file'){app.bankFile=e.target.files[0]||null;$('#bank-file-label').textContent=app.bankFile?.name||'Keine Datei ausgewählt.';}if(e.target.id==='inbox-month'){app.inboxMonth=e.target.value;render();}if(e.target.id==='inbox-filter'){app.inboxFilter=e.target.value;render();}if(e.target.closest('#bank-import-form')&&e.target.name==='year'){const control=$('#bank-import-form [name=account_id]'),previous=control.value;control.innerHTML=options(accountsForYear(Number(e.target.value)).map(a=>[a.id,a.name+(a.status==='closed'?' · Archiv':'')]),previous);}});
document.addEventListener('input',e=>{if(e.target.id==='inbox-search'){const pos=e.target.selectionStart;app.inboxSearch=e.target.value;render();$('#inbox-search').focus();$('#inbox-search').setSelectionRange(pos,pos);}});
